/* Hidden attribute safeguard */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #1e1b2e;
  --card-bg: #2d2640;
  --card-border: #4a3e6d;
  --gold-color: #ffd700;
  --text-main: #f5f3fa;
  --text-dim: #a59ec1;
  --btn-bg: #3c8853;
  --btn-border: #235232;
  --btn-hover: #48a364;
  --btn-active: #1d4329;
  --btn-disabled: #474354;
  --btn-disabled-text: #7e798e;
  --focus-ring: #00e5ff;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  background-color: var(--bg-color);
  color: var(--text-main);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.miner-card {
  background-color: var(--card-bg);
  border: 4px solid var(--card-border);
  border-radius: 12px;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.45);
  width: 100%;
  max-width: 420px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  text-align: center;
}

.card-header .title {
  font-size: 1.5rem;
  letter-spacing: 0.5px;
  color: var(--gold-color);
  margin-bottom: 6px;
}

.card-header .subtitle {
  font-size: 1rem;
  color: var(--text-dim);
}

.canvas-container {
  display: flex;
  justify-content: center;
  align-items: center;
  background: #151320;
  border: 3px solid var(--card-border);
  border-radius: 8px;
  padding: 8px;
}

#pixelCanvas {
  width: 100%;
  max-width: 256px;
  height: auto;
  aspect-ratio: 2 / 1;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  display: block;
}

.stats-board {
  display: flex;
  justify-content: space-around;
  background-color: #231d33;
  border-radius: 8px;
  padding: 14px;
  border: 1px solid var(--card-border);
}

.stat-box {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-label {
  font-size: 1rem;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--gold-color);
}

.actions-section {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.pixel-btn {
  font-family: inherit;
  font-size: 1.05rem;
  font-weight: 600;
  color: #ffffff;
  background-color: var(--btn-bg);
  border: 3px solid var(--btn-border);
  border-radius: 6px;
  padding: 14px 18px;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.05s ease;
  outline: none;
}

.pixel-btn:hover:not(:disabled) {
  background-color: var(--btn-hover);
}

.pixel-btn:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 3px;
}

.pixel-btn:active:not(:disabled) {
  background-color: var(--btn-active);
  transform: translateY(2px);
}

.pixel-btn:disabled {
  background-color: var(--btn-disabled);
  color: var(--btn-disabled-text);
  border-color: #353240;
  cursor: not-allowed;
  opacity: 0.8;
  transform: none;
}

.inventory-info {
  font-size: 1rem;
  color: var(--text-dim);
}

document.addEventListener('DOMContentLoaded', () => {
  const DRILL_COST = 10;
  const BASE_RATE = 1;

  let gold = 0;
  let drills = 0;

  const goldDisplay = document.getElementById('goldDisplay');
  const rateDisplay = document.getElementById('rateDisplay');
  const drillCountDisplay = document.getElementById('drillCountDisplay');
  const buyDrillBtn = document.getElementById('buyDrillBtn');
  const canvas = document.getElementById('pixelCanvas');
  const ctx = canvas.getContext('2d');

  function getGoldPerSecond() {
    return BASE_RATE + drills;
  }

  function updateUI() {
    goldDisplay.textContent = gold;
    rateDisplay.textContent = `${getGoldPerSecond()}/s`;
    drillCountDisplay.textContent = drills;

    const canAfford = gold >= DRILL_COST;
    buyDrillBtn.disabled = !canAfford;
    buyDrillBtn.setAttribute('aria-disabled', String(!canAfford));
  }

  function buyDrill() {
    if (gold >= DRILL_COST) {
      gold -= DRILL_COST;
      drills += 1;
      updateUI();
      drawPixelScene();
    }
  }

  function tick() {
    gold += getGoldPerSecond();
    updateUI();
    drawPixelScene();
  }

  let animFrame = 0;
  function drawPixelScene() {
    animFrame = (animFrame + 1) % 4;
    ctx.fillStyle = '#151320';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Ground rocks / cave background
    ctx.fillStyle = '#3a3452';
    ctx.fillRect(0, 48, 128, 16);

    // Gold vein in the wall
    ctx.fillStyle = '#ffd700';
    ctx.fillRect(100, 20, 8, 8);
    ctx.fillRect(106, 26, 6, 6);
    ctx.fillRect(94, 24, 7, 7);

    // Miner
    ctx.fillStyle = '#4a90e2'; // Shirt
    ctx.fillRect(36, 32, 10, 16);
    ctx.fillStyle = '#ffcc99'; // Face
    ctx.fillRect(37, 24, 8, 8);
    ctx.fillStyle = '#ffd700'; // Miner Helmet
    ctx.fillRect(35, 20, 12, 4);
    ctx.fillStyle = '#ffffff'; // Helmet lamp
    ctx.fillRect(45, 21, 3, 3);

    // Pickaxe swing animation
    ctx.fillStyle = '#8b5a2b'; // Handle
    ctx.fillStyle = '#cccccc'; // Head
    if (animFrame % 2 === 0) {
      ctx.fillRect(46, 28, 12, 3);
      ctx.fillRect(55, 24, 3, 11);
    } else {
      ctx.fillRect(44, 34, 10, 3);
      ctx.fillRect(52, 32, 3, 11);
    }

    // Active drill machines based on purchase
    const drillsToShow = Math.min(drills, 3);
    for (let i = 0; i < drillsToShow; i++) {
      const x = 70 + (i * 10);
      const y = 36;
      ctx.fillStyle = '#e74c3c'; // Drill body
      ctx.fillRect(x, y, 6, 12);
      ctx.fillStyle = '#bdc3c7'; // Bit
      const jitter = (animFrame + i) % 2 === 0 ? 0 : 1;
      ctx.fillRect(x + 6, y + 4 + jitter, 3, 4);
    }
  }

  buyDrillBtn.addEventListener('click', buyDrill);

  // Run 1-second game timer
  setInterval(tick, 1000);

  // Initial render
  updateUI();
  drawPixelScene();
});
